main.script:

document.addEventListener("DOMContentLoaded", function () {
    // Scenario Presets Dictionary
    var presets = {
        mfg: {
            prompt: "Phân tích dữ liệu vi rung động tần số cao trên Trục chính CNC #4, đối chiếu cảnh báo cảm biến nhiệt, truy vết lịch sử bảo trì ERP và tự động sinh lệnh sửa chữa SAP MES.",
            steps: [
                "Agent OCR & Telemetry: Thu nạp 12.000 mẫu gia tốc trục quay CNC #4 từ cảm biến IoT.",
                "Agent Rules Resolver: Phát hiện đỉnh sóng hài 1,84kHz (vòng bi SKF 6208 mỏi 98,4%).",
                "Agent Risk Guardrail: Xác thực định mức an toàn ISO 10816-3. Chặn rủi ro cháy động cơ.",
                "Agent Immutable Audit: Ghi nhận cảnh báo #ALM-CNC04 vào sổ cái kiểm toán bất biến.",
                "Agent 1-Touch Approval: Tự động khởi tạo Lệnh sửa chữa #WO-89104 trên SAP MES."
            ],
            seal: "0x8f2a1b4c9e7d3f5a6b0c2e4d8a1f7c3e5b9a0d2f4e6c8a1b3d5e7f9a0c2e4b6d"
        },
        customs: {
            prompt: "Tiếp nhận bộ hồ sơ XNK lô #VNACCS-7712, đối soát mã HS thép tấm không gỉ giữa Commercial Invoice (7219.33.00) và Tờ khai luồng vàng (7219.34.00), phát hiện chênh lệch thuế suất 8.8%.",
            steps: [
                "Agent OCR & Parser: Trích xuất 14 trang Invoice, Packing List, Mill Test Certificate.",
                "Agent Rules Resolver: Đối chiếu Biểu thuế XNK 2026. Phát hiện sai lệch phân loại HS 8 số.",
                "Agent Risk Guardrail: Kích hoạt Invariant P1 Statutory Rule. Chặn khai báo sai thuế.",
                "Agent Immutable Audit: Đóng dấu bằng chứng đối soát 3 chiều PO-INV-BOM-VNACCS.",
                "Agent 1-Touch Approval: Đề xuất hiệu chỉnh mã HS chuẩn 7219.34.00, tránh phạt truy thu ₫182.400.000."
            ],
            seal: "0x3d7b8e9f1a2c4e6b8d0a2f4c6e8b0d2f4a6c8e0b2d4f6a8c0e2b4d6f8a0c2e4b"
        },
        logistics: {
            prompt: "Đối chiếu Vận đơn B/L đường biển HLCUBSC26084 với Phiếu cân điện tử Cát Lái VGM (Gross Weight: 26.400 kg vs 24.100 kg), kiểm tra hạn chót DEM/DET và tự động kháng nghị cước phụ thu.",
            steps: [
                "Agent OCR & Telemetry: Đọc hiểu B/L Hapag-Lloyd và phiếu cân điện tử Tân Cảng.",
                "Agent Rules Resolver: Phát hiện sai lệch trọng lượng +2.300 kg (vượt dung sai SOLAS 5%).",
                "Agent Risk Guardrail: Truy xuất tọa độ GPS xe đầu kéo và mốc thời gian Gate-in bãi container.",
                "Agent Immutable Audit: Khóa chứng từ đối chiếu trọng lượng, phát hiện phí DEM quá hạn không hợp lệ.",
                "Agent 1-Touch Approval: Tự động gửi công văn kháng nghị hãng tàu, tiết kiệm $650 phụ phí bãi."
            ],
            seal: "0x5a1f7c3e9b0d2f4a6c8e0b2d4f6a8c0e2b4d6f8a0c2e4b6d8f0a2c4e6b8d0a2f"
        },
        telecom: {
            prompt: "Kiểm duyệt luồng video lô #18204 của MobiFone theo quy chuẩn truyền thông, phát hiện watermark trái phép, nội dung độc hại và vi phạm bản quyền.",
            steps: [
                "Agent OCR & Perception: Thu nạp 420 khung hình chính H.264 ở tốc độ 60fps.",
                "Agent Rules Resolver: Phân loại khung hình đa lớp: 0 khung hình độc hại, 0 vi phạm bản quyền.",
                "Agent Risk Guardrail: Bóc băng âm thanh: 100% tuân thủ quy chuẩn Phát thanh - Truyền hình.",
                "Agent Immutable Audit: Đóng dấu sổ cái Watermark số với mã băm SHA-256 #7c9f...a81.",
                "Agent 1-Touch Approval: Lô video được phê duyệt phát sóng tốc độ cao trên mạng CDN."
            ],
            seal: "0x7c9fa81e2b4d6f8a0c2e4b6d8f0a2c4e6b8d0a2f4a6c8e0b2d4f6a8c0e2b4d6f"
        },
        energy: {
            prompt: "Giám sát camera an ninh cổng Trạm biến áp 220kV, xác thực danh tính nhà thầu, kiểm tra mũ bảo hộ, dây an toàn và găng cách điện trước khi mở cổng xoay an toàn.",
            steps: [
                "Agent OCR & Vision: Nhận diện FaceID nhân sự nhà thầu: Nguyễn Văn H. (Mã #EVN-89412).",
                "Agent Rules Resolver: Chứng chỉ An toàn Điện Bậc 4 còn hiệu lực đến 31/12/2027.",
                "Agent Risk Guardrail: Kiểm tra trang bị BHLĐ: Mũ Class-E (ĐẠT), Áo phản quang (ĐẠT), Găng (ĐẠT).",
                "Agent Immutable Audit: Ghi nhận nhật ký kiểm toán SCADA bất biến về trung tâm chỉ huy.",
                "Agent 1-Touch Approval: Mở khóa cổng xoay an toàn #02 trong 15 giây cấp quyền tiếp cận."
            ],
            seal: "0x2e4b6d8f0a2c4e6b8d0a2f4c6e8b0d2f4a6c8e0b2d4f6a8c0e2b4d6f8a0c2e4b"
        }
    };

    // Console Preset Switcher
    var presetButtons = document.querySelectorAll(".mojo-prompt-btn");
    var promptInput = document.getElementById("mojo-console-prompt");
    var consoleOutput = document.getElementById("mojo-console-output");
    var runButton = document.getElementById("mojo-btn-run");
    var pipelineStatus = document.getElementById("mojo-pipeline-status");

    var stepEls = [
        document.getElementById("mojo-step-1"),
        document.getElementById("mojo-step-2"),
        document.getElementById("mojo-step-3"),
        document.getElementById("mojo-step-4"),
        document.getElementById("mojo-step-5")
    ];

    function resetPipelineSteps() {
        stepEls.forEach(function (el) {
            if (el) {
                el.style.background = "#1E293B";
                el.style.borderColor = "#334155";
                el.style.color = "#94A3B8";
            }
        });
    }

    presetButtons.forEach(function (btn) {
        btn.addEventListener("click", function () {
            presetButtons.forEach(function (b) { b.classList.remove("active"); });
            btn.classList.add("active");
            var key = btn.getAttribute("data-preset");
            if (presets[key] && promptInput) {
                promptInput.value = presets[key].prompt;
            }
            resetPipelineSteps();
            if (pipelineStatus) {
                pipelineStatus.textContent = "Sẵn Sàng Tiếp Nhận Tín Hiệu";
                pipelineStatus.style.color = "#38BDF8";
            }
            if (consoleOutput) {
                consoleOutput.textContent = 'Hệ thống sẵn sàng. Nhấp "KÍCH HOẠT ĐIỀU PHỐI MULTI-AGENT" để bắt đầu luồng phối hợp 5 tác nhân AI chuyên trách.';
            }
        });
    });

    // Run Agent Execution Animation with Sequential Illumination & Typing
    if (runButton && promptInput && consoleOutput) {
        runButton.addEventListener("click", function () {
            runButton.disabled = true;
            resetPipelineSteps();

            var activeBtn = document.querySelector(".mojo-prompt-btn.active");
            var key = activeBtn ? activeBtn.getAttribute("data-preset") : "mfg";
            var scenario = presets[key] || presets.mfg;

            if (pipelineStatus) {
                pipelineStatus.textContent = "⚡ Swarm Đang Thực Thi Tuần Tự (5 Agents)...";
                pipelineStatus.style.color = "#00F0FF";
            }

            consoleOutput.textContent = "KHỞI CHẠY HỆ THỐNG MULTI-AGENT INNORIA SWARM · ĐIỀU PHỐI VẬN HÀNH CHỦ QUYỀN...\n";

            var stepIndex = 0;
            function executeNextStep() {
                if (stepIndex < scenario.steps.length) {
                    var currentEl = stepEls[stepIndex];
                    if (currentEl) {
                        currentEl.style.background = "#064E3B";
                        currentEl.style.borderColor = "#10B981";
                        currentEl.style.color = "#A7F3D0";
                    }

                    var stepLine = "► [" + (stepIndex + 1) + "/5] " + scenario.steps[stepIndex] + "\n";
                    consoleOutput.textContent += stepLine;
                    stepIndex++;
                    setTimeout(executeNextStep, 280);
                } else {
                    var finishBlock = "\n" +
                        "========================================================================\n" +
                        "TRẠNG THÁI: HOÀN TẤT · 100% TUÂN THỦ QUY TRÌNH & HÀNG RÀO BẢO VỆ\n" +
                        "MÃ BĂM BẤT BIẾN (SHA-256 SEAL): " + scenario.seal + "\n" +
                        "THỜI GIAN ĐIỀU PHỐI SWARM: 214ms | 0 NGOẠI LỆ TỒN ĐỌNG\n" +
                        "========================================================================";
                    consoleOutput.textContent += finishBlock;
                    if (pipelineStatus) {
                        pipelineStatus.textContent = "✓ Hoàn Tất Toàn Vẹn · Seal Hash Đã Lưu";
                        pipelineStatus.style.color = "#34D399";
                    }
                    runButton.disabled = false;
                }
            }

            setTimeout(executeNextStep, 200);
        });
    }

    // Live Telemetry HUD Simulation
    setInterval(function () {
        var latencyEl = document.getElementById("hud-latency");
        var tokensEl = document.getElementById("hud-tokens");
        var accuracyEl = document.getElementById("hud-accuracy");
        var latencyBar = document.getElementById("hud-latency-bar");
        var tokensBar = document.getElementById("hud-tokens-bar");

        if (latencyEl) {
            var lat = 210 + Math.floor(Math.random() * 32);
            latencyEl.textContent = lat;
            if (latencyBar) latencyBar.style.width = Math.min(100, Math.floor((lat / 300) * 100)) + "%";
        }
        if (tokensEl) {
            var tok = 142 + Math.floor(Math.random() * 24);
            tokensEl.textContent = tok;
            if (tokensBar) tokensBar.style.width = Math.min(100, Math.floor((tok / 180) * 100)) + "%";
        }
        if (accuracyEl) {
            accuracyEl.textContent = (99.7 + Math.random() * 0.2).toFixed(1);
        }
    }, 1600);

    // Live Log Feed Append
    var streamBox = document.getElementById("hud-stream-logs");
    var logSamples = [
        "[BĂNG-CHUYỀN-02] Đếm quang học thời gian thực: 1.480 sp/phút. Tỷ lệ lỗi: 0,00%.",
        "[CSKH-VIỄN-THÔNG] Điều hướng cảm xúc khách hàng: 94,2% hài lòng trên tuyến xử lý cước.",
        "[LƯỚI-ĐIỆN] Hệ số công suất lộ xuất tuyến #14 tối ưu hóa đạt 0,98. Tổn thất phản kháng tối thiểu.",
        "[BỘ-ĐIỀU-PHỐI] Kiểm toán hạn mức thụ động: 0 yêu cầu scraping ra ngoài.",
        "[THỊ-GIÁC-AI] Ảnh nhiệt máy biến áp trạm: Nhiệt độ đỉnh 48,2°C (Ngưỡng an toàn: 75°C).",
        "[ĐỒNG-BỘ-ERP] Lệnh sửa chữa SAP #WO-89105: Đã được Trưởng ca bảo trì phê duyệt."
    ];

    setInterval(function () {
        if (streamBox) {
            var now = new Date();
            var timeStr = now.toTimeString().split(" ")[0];
            var item = logSamples[Math.floor(Math.random() * logSamples.length)];
            var newRow = document.createElement("div");
            newRow.className = "text-muted mb-1";
            newRow.innerHTML = '<span class="text-secondary">[' + timeStr + ']</span> ' + item;
            streamBox.appendChild(newRow);
            if (streamBox.childNodes.length > 25) {
                streamBox.removeChild(streamBox.firstChild);
            }
            streamBox.scrollTop = streamBox.scrollHeight;
        }
    }, 2400);
});
